      && verifier.VerifyString(tablePos, 6 /*TRAJ_ID*/, false)
      && verifier.VerifyString(tablePos, 8 /*TRAJ_PREV_ID*/, false)
      && verifier.VerifyString(tablePos, 10 /*TRAJ_NEXT_ID*/, false)
      && verifier.VerifyString(tablePos, 12 /*TRAJ_BASIS*/, false)
      && verifier.VerifyString(tablePos, 14 /*TRAJ_BASIS_ID*/, false)
      && verifier.VerifyString(tablePos, 16 /*INTERPOLATION*/, false)
      && verifier.VerifyField(tablePos, 18 /*INTERPOLATION_DEGREE*/, 4 /*uint*/, 4, false)
      && verifier.VerifyString(tablePos, 20 /*PROPAGATOR*/, false)
      && verifier.VerifyString(tablePos, 22 /*CENTER_NAME*/, false)
      && verifier.VerifyString(tablePos, 24 /*TRAJ_REF_FRAME*/, false)
      && verifier.VerifyString(tablePos, 26 /*TRAJ_FRAME_EPOCH*/, false)
      && verifier.VerifyString(tablePos, 28 /*USEABLE_START_TIME*/, false)
      && verifier.VerifyString(tablePos, 30 /*USEABLE_STOP_TIME*/, false)
      && verifier.VerifyField(tablePos, 32 /*ORB_REVNUM*/, 8 /*double*/, 8, false)
      && verifier.VerifyField(tablePos, 34 /*ORB_REVNUM_BASIS*/, 4 /*int*/, 4, false)
      && verifier.VerifyString(tablePos, 36 /*TRAJ_TYPE*/, false)
      && verifier.VerifyString(tablePos, 38 /*ORB_AVERAGING*/, false)
      && verifier.VerifyString(tablePos, 40 /*TRAJ_UNITS*/, false)
      && verifier.VerifyVectorOfStrings(tablePos, 42 /*LINES*/, false)
      && verifier.VerifyTableEnd(tablePos);
  }
}
